import java.net.*;import java.nio.file.*;
/** Flight collision, repeated visual snapshots and missing-weapon diagnosis. */
public class Battle754Check {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS: "+s);}
 static void stale(Battle b){b.units[0].landingTicks=32;b.units[0].flashTicks=36;b.damagePopupCount=0;b.showDamage(b.units[1],123,false);Battle.Blast f=new Battle.Blast();f.x=350;f.y=170;f.weapon=0;b.blasts[0]=f;b.blastCount=1;}
 public static void main(String[] args)throws Exception{
  Battle b=Items710ServerCheck.fresh();b.wind=0;Battle.Unit u=b.units[0],enemy=b.units[1];enemy.x=200;enemy.y=170;int hp=enemy.hp;Battle.Ball plane=new Battle.Ball();plane.fly=true;plane.owner=0;plane.x=enemy.x*256;plane.y=(enemy.y-12)*256;plane.vx=plane.vy=0;b.balls[0]=plane;b.ballCount=1;b.tick();ok(b.ballCount==1&&enemy.hp==hp,"Flight passes through enemy body without damage or disappearance");plane.x=enemy.x*256;plane.y=170*256;b.impact(plane);ok(u.x==enemy.x&&u.y==170&&u.landingTicks==32&&enemy.hp==hp,"Flight lands on occupied ground without damaging either player");
  int landing=u.x;b.ballCount=0;b.bursts=0;b.settle=0;u.energy=240;b.move(-1);ok(u.x==landing-1,"Player can walk away after landing at the enemy position");b.move(1);ok(u.x==landing-1,"Walking back into enemy collision remains blocked");
  b=Items710ServerCheck.fresh();OnlineVisuals v=new OnlineVisuals();int x=b.units[0].x,turn=b.turn,clock=b.countdown;stale(b);v.age(b,10000);for(int i=1;i<=60;i++){stale(b);v.age(b,10000+i*33L);}ok(b.units[0].landingTicks==0&&b.units[0].flashTicks==0&&b.damagePopupCount==0&&b.blastCount==0,"Repeated age-zero snapshot cannot freeze or resurrect visual effects");ok(b.units[0].x==x&&b.turn==turn&&b.countdown==clock,"Presentation clocks do not change physics or countdown");b.shotSerial++;b.hitSerial++;stale(b);v.age(b,12000);ok(b.damagePopupCount==1&&b.units[0].landingTicks==32,"New shot at identical coordinates still shows its effects");v.reset();stale(b);v.age(b,13000);ok(b.damagePopupCount==1,"New match resets the visual clock cache");
  CloudStore.Memory store=new CloudStore.Memory();store.register("a@754.test","test-password-123","A");try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){
   ServerCheck.base="http://127.0.0.1:"+server.port();String token=Equipment718ServerCheck.login("a@754.test");int id=Equipment718ServerCheck.call(token,"create",out->{out.writeByte(1);out.writeByte(0);out.writeByte(-1);}).readInt();var s=server.sessions.get(token);s.profile.wornMask=s.profile.owned=0;var room=server.rooms.get(id);synchronized(room){try{server.matchmaker.start(s,0,"");throw new AssertionError("Unarmed queue accepted");}catch(IllegalArgumentException expected){ok(expected.getMessage().equals("Không có trang bị vũ khí không thể bắt đầu"),"Unarmed start reports weapon requirement before waiting for allies");}ok(!room.queued,"Unarmed player never joins matchmaking");}Features753Check.base=ServerCheck.base;try{Features753Check.call(token,"quick",out->out.writeByte(1));throw new AssertionError("Unarmed quick accepted");}catch(java.io.IOException expected){ok(expected.getMessage().contains("Không có trang bị vũ khí"),"HTTP solo shortcut rejects missing weapon");}try{Features753Check.call(token,"ready",out->out.writeBoolean(true));throw new AssertionError("Unarmed ready accepted");}catch(java.io.IOException expected){ok(expected.getMessage().contains("Không có trang bị vũ khí"),"HTTP ready rejects missing weapon");}
  }
  CloudStore.Memory chunkStore=new CloudStore.Memory();chunkStore.register("chunks@755.test","test-password-123","Chunks");try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),chunkStore)){ServerCheck.base="http://127.0.0.1:"+server.port();String token=Equipment718ServerCheck.login("chunks@755.test");int id=Equipment718ServerCheck.call(token,"create",out->{out.writeByte(1);out.writeByte(0);out.writeByte(-1);}).readInt();var room=server.rooms.get(id);synchronized(room){room.strict=false;room.start();room.powTicks=150;room.chunkBegin(2);for(int i=149;i>=0;i--){room.powTicks=i;room.chunkFrame();}room.chunkFlush(false);int count=0;for(byte[] block:room.chunks){ok(block.length<=16384,"POW playback packet fits handset limit");var in=new java.io.DataInputStream(new java.io.ByteArrayInputStream(block));ok(in.readUnsignedByte()==2&&!in.readBoolean(),"Split POW preserves kind and nonterminal flag");count+=in.readUnsignedShort();}ok(count==151&&room.chunks.size()>1,"POW split preserves every frame");}}
  System.out.println("All battle 7.5.4 checks passed");
 }
}
